H.background();
const w = H.W;
const N0 = Math.max(1, P.N0);          // initial number of nuclei
const thalf = Math.max(0.2, P.thalf);  // half-life (seconds)
const lambda = Math.LN2 / thalf;       // decay constant
const tMax = thalf * 5;
const v = H.plot2d({ xMin: 0, xMax: tMax, yMin: 0, yMax: N0 * 1.08 });
v.grid(); v.axes();
// Decay curve N(t) = N0 e^(-lambda t).
v.fn(x => N0 * Math.exp(-lambda * x), { color: H.colors.accent, width: 3 });
// Half-life gridlines: N0/2, N0/4, ... at t = thalf, 2 thalf, ...
for (let k = 1; k <= 4; k++) {
  const tk = k * thalf, Nk = N0 * Math.pow(0.5, k);
  v.line(tk, 0, tk, Nk, { color: H.colors.violet, width: 1, dash: [4, 4] });
  v.line(0, Nk, tk, Nk, { color: H.colors.violet, width: 1, dash: [4, 4] });
  v.dot(tk, Nk, { r: 4, fill: H.colors.violet });
}
// Animated current-time marker sweeping the curve and looping.
const tc = (t * (tMax / 6)) % tMax;
const Nc = N0 * Math.exp(-lambda * tc);
v.line(tc, 0, tc, Nc, { color: H.colors.warn, width: 1.5 });
v.dot(tc, Nc, { r: 7, fill: H.colors.warn });
H.text("Radioactive decay: N = N0·e^(−λt)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("N0 = " + N0.toFixed(0) + "    t½ = " + thalf.toFixed(2) + " s    λ = ln2/t½ = " + lambda.toFixed(3) + " /s", 24, 52, { color: H.colors.sub, size: 12 });
H.text("t = " + tc.toFixed(2) + " s   →   N = " + Nc.toFixed(1) + "   (" + (100 * Nc / N0).toFixed(1) + "% left)", 24, 74, { color: H.colors.good, size: 13 });
H.legend([{ label: "N(t)", color: H.colors.accent }, { label: "half-life steps", color: H.colors.violet }], w - 180, 28);
